20	/**
21	 * An HTML Form Element provides ready access to the form fields/controls that are associated with it. It also allows a
22	 * form to easily be submitted.
23	 */
24	public class FormElement extends Element {
25	    private final Elements linkedEls = new Elements();
26	    // contains form-listed elements that were linked during the parse (and due to parse rules, e.g. foster parenting in
27	    // tables, may no longer be a descendant of this form)
28	    private static final String[] FormListedTags = {
29	        "button", "fieldset", "input", "keygen", "object", "output", "select", "textarea"
30	    };
31	    private static final Evaluator listed = Selector.evaluatorOf(StringUtil.join(FormListedTags, ", "));
32	
33	    /**
34	     * Create a new, standalone form element.
35	     *
36	     * @param tag        tag of this element
37	     * @param baseUri    the base URI
38	     * @param attributes initial attributes
39	     */
40	    public FormElement(Tag tag, @Nullable String baseUri, @Nullable Attributes attributes) {
41	        super(tag, baseUri, attributes);
42	    }
43	
44	    /**
45	     Get the list of form control elements associated with this form.
46	     <p>Association follows the current state of the DOM, not just the state captured during the parse:</p>
47	     <ol>
48	     <li>A control with a {@code form} attribute is associated only with the first {@code <form>} in the same document
49	     whose {@code id} matches. An attribute that is empty, or that points to an unknown id, associates the control with
50	     no form &mdash; it does not fall back to an ancestor form.</li>
51	     <li>Otherwise, a control is associated with its nearest ancestor {@code <form>}.</li>
52	     <li>Controls that the parser associated with this form but which the parser placed outside of any form subtree
53	     (such as controls fostered out of a form in a table) remain associated while they are untouched.</li>
54	     </ol>
55	     <p>Changes made after parsing &mdash; moving controls, adding or removing a {@code form} attribute, or changing a
56	     form's {@code id} &mdash; are reflected on the next call. Moving a control drops its parser-time association.</p>
57	     @return form controls associated with this element, in document order
58	     */
59	    public Elements elements() {
60	        Elements members = new Elements();
61	        Document doc = ownerDocument();
62	
63	        // all candidate controls: the whole document when attached (to catch form=attr controls outside the subtree),
64	        // otherwise just this form and its descendants
65	        Elements candidates = doc != null ? Collector.collect(listed, doc) : select(listed);
66	
67	        @Nullable Elements docForms = doc != null ? doc.getElementsByTag("form") : null;
68	        for (Element el : candidates) {
69	            if (isAssociated(el, doc, docForms))
70	                members.add(el);
71	        }
72	        // retain parser-linked controls (e.g. fostered out of tables, or added to a detached form) not in candidate scope
73	        for (Element linkedEl : linkedEls) {
74	            if (!members.contains(linkedEl) && (doc == null || linkedEl.ownerDocument() == doc)
75	                && isAssociated(linkedEl, doc, docForms)) {
76	                members.add(linkedEl);
77	            }
78	        }
79	        members.sort(FormElement::documentOrder);
80	        return members;
81	    }
82	
83	    /** Determine if the control's current form owner is this form, per the association rules in {@link #elements()}. */
84	    private boolean isAssociated(Element el, @Nullable Document doc, @Nullable Elements docForms) {
85	        if (el.hasAttr("form")) {
86	            String id = el.attr("form");
87	            if (id.length() == 0 || doc == null || docForms == null) return false; // explicit but unresolvable: no owner, no fallback
88	            for (Element form : docForms) {
89	                if (form instanceof FormElement && id.equals(form.id()))
90	                    return form == this; // first form with a matching id wins; duplicate ids are ignored
91	            }
92	            return false;
93	        }
94	
95	        for (Element parent = el.parent(); parent != null; parent = parent.parent()) {
96	            if (parent instanceof FormElement)
97	                return parent == this; // nearest ancestor form
98	        }
99	
100	        // no form attribute and no ancestor form: a parser-linked orphan still counts, but only while it has not been
101	        // moved away from the parent it had when the parser placed it (e.g. foster-parented out of a table)
102	        if (!linkedEls.contains(el)) return false;
103	        Object orphanParent = el.attributes().userData(SharedConstants.FormOrphanParentKey);
104	        if (orphanParent == null) return false;
105	        return orphanParent == ORPHAN_DETACHED ? el.parent() == null : orphanParent == el.parent();
106	    }
107	
108	    // sentinel for a control explicitly linked while detached, before it has a parent
109	    private static final Object ORPHAN_DETACHED = new Object();
110	
111	    /**
112	     * Add a form control element to this form.
113	     * @param element form control to add
114	     * @return this form element, for chaining
115	     */
116	    public FormElement addElement(Element element) {
117	        linkElement(element);
118	        markOrphanControl(element);
119	        return this;
120	    }
121	
122	    /** Link a control to this form, without recording its placement (the parser marks placement after insertion). */
123	    void linkElement(Element element) {
124	        linkedEls.add(element);
125	    }
126	
127	    static boolean isDescendant(Node node, Element ancestor) {
128	        for (Node parent = node.parent(); parent != null; parent = parent.parent()) {
129	            if (parent == ancestor) return true;
130	        }
131	        return false;
132	    }
133	
134	    /**
135	     Record the current parent of a linked control that is outside this form's subtree (or detached), so the orphan
136	     fallback holds only while it stays in that placement. Controls inside the form's subtree are governed by the
137	     ancestor rule and need no marker.
138	     */
139	    void markOrphanControl(Element element) {
140	        if (isDescendant(element, this))
141	            element.attributes().userData(SharedConstants.FormOrphanParentKey, null); // clear any stale marker
142	        else
143	            element.attributes().userData(SharedConstants.FormOrphanParentKey,
144	                element.parent() != null ? element.parent() : ORPHAN_DETACHED);
145	    }
146	
147	    @Override
148	    protected void removeChild(Node out) {
149	        super.removeChild(out);
150	        linkedEls.remove(out);
151	    }
152	
153	    /**
154	     Prepare to submit this form. A Connection object is created with the request set up from the form values. This
155	     Connection will inherit the settings and the cookies (etc) of the connection/session used to request this Document
156	     (if any), as available in {@link Document#connection()}
157	     <p>You can then set up other options (like user-agent, timeout, cookies), then execute it.</p>
158	
159	     @return a connection prepared from the values of this form, in the same session as the one used to request it
160	     @throws IllegalArgumentException if the form's absolute action URL cannot be determined. Make sure you pass the
161	     document's base URI when parsing.
162	     */
163	    public Connection submit() {
164	        String action = hasAttr("action") ? absUrl("action") : baseUri();
165	        Validate.notEmpty(action, "Could not determine a form action URL for submit. Ensure you set a base URI when parsing.");
166	        Connection.Method method = attr("method").equalsIgnoreCase("POST") ?
167	            Connection.Method.POST : Connection.Method.GET;
168	
169	        Document owner = ownerDocument();
170	        Connection connection = owner != null? owner.connection().newRequest() : Jsoup.newSession();
171	        return connection.url(action)
172	            .data(formData())
173	            .method(method);
174	    }
175	
176	    /**
177	     Get the data that this form submits. The returned list is a copy of the data, and changes to the contents of the
178	     list will not be reflected in the DOM.
179	     <p>Only successful controls are included, matching browser form submission rules: controls without a
180	     {@code name}, disabled controls, and controls disabled through a {@code <fieldset disabled>} ancestor are skipped
181	     (controls in the fieldset's first {@code <legend>} subtree are exempt). For {@code <select>}, disabled options and
182	     options in a disabled {@code <optgroup>} are skipped; a non-multiple select with no selected option contributes its
183	     first available option. Checkboxes and radios are only included when checked, defaulting to the value
184	     {@code on}; {@code <input type=button>} and {@code type=reset>} are never included.</p>
185	     <p>As no submitter is given, submit buttons &mdash; {@code <input type=submit>}, {@code <input type=image>}, and
186	     a {@code <button>} whose {@code type} is {@code submit} (the default) &mdash; are not treated as ordinary fields
187	     and contribute nothing. Activate the form through one of them with {@link #formData(Element)} to include that
188	     submitter.</p>
189	     @return a list of key vals, in the order the controls appear in the document; empty if none apply
190	     @see #formData(Element)
191	     */
192	    public List<Connection.KeyVal> formData() {
193	        return formData(null);
194	    }
195	
196	    /**
197	     Get the data that this form submits when activated through {@code submitter}. Behaves like {@link #formData()},
198	     but additionally includes the one activated submit button, in its document-order position among the other
199	     controls; every other submit button remains excluded.
200	     <p>The submitter may be an {@code <input type=submit>}, an {@code <input type=image>}, or a {@code <button>}
201	     whose {@code type} is {@code submit} (the default). Per the browser convention, an image control contributes its
202	     click coordinates, {@code x=0} and {@code y=0} (or {@code <name>.x=0} and {@code <name>.y=0} when named); an
203	     unnamed submit input or button contributes nothing. The submitter must be enabled and associated with this
204	     form.</p>
205	     @param submitter the button used to activate the form, or {@code null} to collect without a submitter
206	     @return a list of key vals, in the order the controls appear in the document; empty if none apply
207	     @throws IllegalArgumentException if the submitter is not an enabled submit button associated with this form
208	     */
209	    public List<Connection.KeyVal> formData(@Nullable Element submitter) {
210	        Elements controls = elements();
211	        if (submitter != null) {
212	            String submitterType = submitter.attr("type");
213	            if (!isSubmitControl(submitter, submitterType) || submitter.hasAttr("disabled")
214	                || isInDisabledFieldset(submitter) || !controls.contains(submitter)) {
215	                throw new IllegalArgumentException(
216	                    "Submitter must be an enabled submit button associated with this form.");
217	            }
218	        }
219	
220	        ArrayList<Connection.KeyVal> data = new ArrayList<>();
221	
222	        // iterate the associated form controls and accumulate their values
223	        for (Element el : controls) {
224	            String type = el.attr("type");
225	            boolean submitControl = isSubmitControl(el, type);
226	            if (!submitControl && !el.tag().isFormSubmittable()) continue; // <button> is listed but not flagged submittable
227	            if (el.hasAttr("disabled")) continue; // skip disabled form inputs
228	            String name = el.attr("name");
229	
230	            if (submitControl) {
231	                // a submit button is only successful when it is the explicit submitter
232	                if (el == submitter)
233	                    addSubmitterData(el, name, type, data);
234	                continue;
235	            }
236	
237	            if (name.length() == 0) continue;
238	            if (type.equalsIgnoreCase("button") || type.equalsIgnoreCase("reset")) continue; // never submitted
239	
240	            if (isInDisabledFieldset(el)) continue; // first legend subtree of a disabled fieldset is exempt
241	
242	            if (el.nameIs("select")) {
243	                addSelectData(el, name, data);
244	            } else if ("checkbox".equalsIgnoreCase(type) || "radio".equalsIgnoreCase(type)) {
245	                // only add checkbox or radio if they have the checked attribute
246	                if (el.hasAttr("checked")) {
247	                    final String val = el.hasAttr("value") ? el.attr("value") : "on";
248	                    data.add(HttpConnection.KeyVal.create(name, val));
249	                }
250	            } else {
251	                // textarea#val() returns its text; other controls use their value attribute
252	                data.add(HttpConnection.KeyVal.create(name, el.val()));
253	            }
254	        }
255	        return data;
256	    }
257	
258	    /**
259	     A control that is successful only when it activated the form: an {@code <input type=submit>},
260	     {@code <input type=image>}, or a {@code <button>} that is not {@code type=button} or {@code type=reset}
261	     (a button without a {@code type} defaults to {@code submit}).
262	     */
263	    private static boolean isSubmitControl(Element el, String type) {
264	        if (el.nameIs("button"))
265	            return !"button".equalsIgnoreCase(type) && !"reset".equalsIgnoreCase(type);
266	        return el.nameIs("input")
267	            && ("submit".equalsIgnoreCase(type) || "image".equalsIgnoreCase(type));
268	    }
269	
270	    /** Append the value an activated submit button contributes (nothing for an unnamed submit/button). */
271	    private static void addSubmitterData(Element el, String name, String type, ArrayList<Connection.KeyVal> data) {
272	        if ("image".equalsIgnoreCase(type)) {
273	            // image buttons submit the clicked coordinates, with the name prefixed when present
274	            String prefix = name.length() == 0 ? "" : name + ".";
275	            data.add(HttpConnection.KeyVal.create(prefix + "x", "0"));
276	            data.add(HttpConnection.KeyVal.create(prefix + "y", "0"));
277	        } else if (name.length() > 0) {
278	            data.add(HttpConnection.KeyVal.create(name, el.val()));
279	        }
280	    }
281	
282	    private static void addSelectData(Element select, String name, ArrayList<Connection.KeyVal> data) {
283	        boolean multiple = select.hasAttr("multiple");
284	        boolean added = false;
285	
286	        // selected options, in document order, skipping disabled options and options in disabled optgroups
287	        for (Element option : select.select("option[selected]")) {
288	            if (!optionIsDisabled(select, option)) {
289	                data.add(HttpConnection.KeyVal.create(name, optionValue(option)));
290	                added = true;
291	            }
292	        }
293	
294	        if (!added && !multiple) {
295	            // a single select with no valid selection contributes the first available option, if any
296	            for (Element option : select.select("option")) {
297	                if (!optionIsDisabled(select, option)) {
298	                    data.add(HttpConnection.KeyVal.create(name, optionValue(option)));
299	                    break;
300	                }
301	            }
302	        }
303	        // a multiple select with no valid selection contributes nothing
304	    }
305	
306	    /** An option is unavailable if it is itself disabled, or if it sits in a disabled optgroup within the select. */
307	    private static boolean optionIsDisabled(Element select, Element option) {
308	        if (option.hasAttr("disabled")) return true;
309	        for (Element parent = option.parent(); parent != null && parent != select; parent = parent.parent()) {
310	            if (parent.nameIs("optgroup") && parent.hasAttr("disabled")) return true;
311	        }
312	        return false;
313	    }
314	
315	    /** Options without a value attribute submit their text content. */
316	    private static String optionValue(Element option) {
317	        return option.hasAttr("value") ? option.attr("value") : option.text();
318	    }
319	
320	    /**
321	     A control barred by a disabled fieldset ancestor. Any disabled fieldset on the ancestor chain bars the control,
322	     unless the control is a descendant of that fieldset's first {@code <legend>} child.
323	     */
324	    private static boolean isInDisabledFieldset(Element control) {
325	        for (Element parent = control.parent(); parent != null; parent = parent.parent()) {
326	            if (parent.nameIs("fieldset") && parent.hasAttr("disabled")) {
327	                Element firstLegend = null;
328	                for (Element child : parent.children()) {
329	                    if (child.nameIs("legend")) {
330	                        firstLegend = child;
331	                        break;
332	                    }
333	                }
334	                boolean inFirstLegend = false;
335	                if (firstLegend != null) {
336	                    for (Element p = control.parent(); p != null && p != parent; p = p.parent()) {
337	                        if (p == firstLegend) {
338	                            inFirstLegend = true;
339	                            break;
340	                        }
341	                    }
342	                }
343	                if (!inFirstLegend) return true;
344	            }
345	        }
346	        return false;
347	    }
348	
349	    /** Compare two nodes by their position in the document tree; nodes in different trees order by tree identity. */
350	    private static int documentOrder(Node a, Node b) {
351	        if (a == b) return 0;
352	        ArrayList<Node> chainA = ancestorChain(a);
353	        ArrayList<Node> chainB = ancestorChain(b);
354	        Node rootA = chainA.get(0);
355	        Node rootB = chainB.get(0);
356	        if (rootA != rootB) // detached trees: keep a deterministic, transitive order
357	            return Integer.compare(System.identityHashCode(rootA), System.identityHashCode(rootB));
358	        int shared = Math.min(chainA.size(), chainB.size());
359	        for (int i = 1; i < shared; i++) {
360	            Node na = chainA.get(i);
361	            Node nb = chainB.get(i);
362	            if (na != nb) {
363	                // chains diverge at this level; compare sibling position under the common parent
364	                return Integer.compare(na.siblingIndex(), nb.siblingIndex());
365	            }
366	        }
367	        // one node is an ancestor of the other; the ancestor (shorter chain) comes first
368	        return Integer.compare(chainA.size(), chainB.size());
369	    }
370	
371	    private static ArrayList<Node> ancestorChain(Node node) {
372	        ArrayList<Node> chain = new ArrayList<>();
373	        for (Node n = node; n != null; n = n.parent())
374	            chain.add(n);
375	        Collections.reverse(chain);
376	        return chain;
377	    }
378	
379	    @Override
380	    public FormElement clone() {
381	        return (FormElement) super.clone();
382	    }
383	}
