package org.jsoup.nodes;

import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.junit.jupiter.api.Test;

import java.util.List;
import java.util.stream.Collectors;

import static org.junit.jupiter.api.Assertions.*;

public class FormAttrScratchTest {
    private static List<String> kv(List<Connection.KeyVal> data) {
        return data.stream().map(k -> k.key() + "=" + k.value()).collect(Collectors.toList());
    }

    @Test void externalControlsInterleaveInDocumentOrder() {
        Document doc = Jsoup.parse(
            "<input form=f name=a value=1>" +
            "<form id=f><input name=b value=2></form>" +
            "<div><span><input form=f name=c value=3></span></div>" +
            "<select form=f name=d><option value=4 selected></select>" +
            "<textarea form=f name=e>5</textarea><button form=f name=g value=6 type=button></button>");
        FormElement form = (FormElement) doc.selectFirst("form");
        assertEquals("[a=1, b=2, c=3, d=4, e=5]", kv(form.formData()).toString());
        // repeated calls stable
        assertEquals(kv(form.formData()), kv(form.formData()));
    }

    @Test void formAttrWinsOverAncestorForm() {
        Document doc = Jsoup.parse(
            "<form id=outer><input form=inner name=x value=1></form><form id=inner></form>");
        FormElement outer = (FormElement) doc.select("form").get(0);
        FormElement inner = (FormElement) doc.select("form").get(1);
        assertEquals("[]", kv(outer.formData()).toString());
        assertEquals("[x=1]", kv(inner.formData()).toString());
    }

    @Test void formWithoutIdDoesNotAbsorb() {
        Document doc = Jsoup.parse("<form><input name=a value=1></form><input form=f name=b value=2><input form name=c value=3>");
        FormElement form = (FormElement) doc.selectFirst("form");
        assertEquals("[a=1]", kv(form.formData()).toString());
    }

    @Test void mutationsReflectedImmediately() {
        Document doc = Jsoup.parse("<form id=f><input name=a value=1></form><input name=b value=2>");
        FormElement form = (FormElement) doc.selectFirst("form");
        Element ext = doc.select("input").get(1);
        assertEquals("[a=1]", kv(form.formData()).toString());

        ext.attr("form", "f");
        assertEquals("[a=1, b=2]", kv(form.formData()).toString());

        form.attr("id", "g"); // id changed: association broken
        assertEquals("[a=1]", kv(form.formData()).toString());

        ext.attr("form", "g");
        ext.attr("disabled", "");
        assertEquals("[a=1]", kv(form.formData()).toString());
        ext.removeAttr("disabled");

        // move external control before the form
        doc.body().prependChild(ext);
        assertEquals("[b=2, a=1]", kv(form.formData()).toString());

        // remove it entirely
        ext.remove();
        assertEquals("[a=1]", kv(form.formData()).toString());

        // add a new external control
        doc.body().appendChild(new Element("input").attr("form", "g").attr("name", "c").attr("value", "3"));
        assertEquals("[a=1, c=3]", kv(form.formData()).toString());
    }

    @Test void externalControlSharesSuccessfulRules() {
        Document doc = Jsoup.parse(
            "<form id=f></form>" +
            "<input form=f name=n1>" + // no value -> empty
            "<input form=f type=checkbox name=n2>" + // unchecked: skipped
            "<input form=f type=checkbox name=n3 checked>" + // checked, no value -> on
            "<fieldset disabled><input form=f name=n4 value=x></fieldset>" +
            "<input form=f type=submit name=n5 value=s>");
        FormElement form = (FormElement) doc.selectFirst("form");
        assertEquals("[n1=, n3=on]", kv(form.formData()).toString());
    }

    @Test void duplicateIdsFirstWinsAndBrokenMarkupOk() {
        Document doc = Jsoup.parse("<form id=f></form><form id=f><input name=a value=1></form><input form=f name=b value=2>");
        FormElement first = (FormElement) doc.select("form").get(0);
        FormElement second = (FormElement) doc.select("form").get(1);
        assertEquals("[b=2]", kv(first.formData()).toString());
        assertEquals("[a=1]", kv(second.formData()).toString());

        Document broken = Jsoup.parse("<form id=f><input name=a value=1");
        assertDoesNotThrow(() -> ((FormElement) broken.selectFirst("form")).formData());
        Document empty = Jsoup.parse("<form id=f></form>");
        assertEquals("[]", kv(((FormElement) empty.selectFirst("form")).formData()).toString());
    }

    @Test void formDataDoesNotMutateDom() {
        String html = "<form id=f><input name=a value=1><select name=s><option selected value=o></select></form><input form=f name=b value=2>";
        Document doc = Jsoup.parse(html);
        FormElement form = (FormElement) doc.selectFirst("form");
        form.formData();
        form.elements();
        assertEquals(Jsoup.parse(html).body().html(), doc.body().html());
    }
}

